'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),vm=require('node:vm');
function setup(){const c={window:{}};vm.createContext(c);for(const f of ['white-orchard.js','map-data.js','progression-data.js','diagrams-data.js','progression-engine.js'])vm.runInContext(fs.readFileSync(f,'utf8'),c);const w=c.window;return {w,engine:w.createPhoenixProgress(w.PHOENIX_PROGRESS_DATA,w.PHOENIX_ROUTE.tasks,w.PHOENIX_ROUTE.hubs)};}
test('every named diagram has one canonical record and valid cluster and map references',()=>{const {w}=setup(),entries=w.PHOENIX_DIAGRAMS.entries,{tasks,hubs}=w.PHOENIX_ROUTE;assert.equal(new Set(entries.map(d=>d.id)).size,entries.length);for(const d of entries){assert.equal(tasks[d.id].view,d.view);assert.equal(d.point.length,2);assert.ok(d.point.every(Number.isFinite));for(const id of d.clusters)assert.ok(hubs.find(h=>h.id===id).items.includes(d.id));}});
test('Viper pins open distinct exact diagram entries instead of a shared whole quest',()=>{const {w}=setup();assert.equal(w.PHOENIX_MAP.markers.find(p=>p.id==='viper-steel').task,'diagram-viper-steel');assert.equal(w.PHOENIX_MAP.markers.find(p=>p.id==='viper-silver').task,'diagram-viper-silver');});
test('acquiring one diagram neither acquires its sibling nor completes a scavenger hunt',()=>{const {engine}=setup(),p=engine.init(),plan=engine.plan(p,{}, {kind:'activity',id:'diagram-viper-steel',value:true});assert.equal(plan.completed['diagram-viper-steel'],true);assert.notEqual(plan.completed['diagram-viper-silver'],true);assert.notEqual(plan.completed['q-viper'],true);assert.equal(Object.keys(plan.progress.objectives).length,0);});
test('legacy whole-quest completion does not silently acquire any new individual diagram',()=>{const {engine}=setup();const p=engine.init({}, {'q-viper':true});const result=engine.plan(p,{'q-viper':true},{kind:'activity',id:'diagram-viper-steel',value:false});assert.equal(result.completed['q-viper'],true);assert.notEqual(result.completed['diagram-viper-silver'],true);});
test('diagrams offered by multiple merchants still have one shared acquisition ID',()=>{const {w}=setup(),matches=w.PHOENIX_DIAGRAMS.entries.filter(d=>d.name==="Tracker's boots diagram");assert.equal(matches.length,1);assert.ok(matches[0].vendors.includes('willis'));assert.ok(matches[0].vendors.includes('sawmill'));});
test('variable source leads never become guaranteed named acquisitions',()=>{const {w}=setup();assert.ok(w.PHOENIX_DIAGRAMS.randomSources.length>0);for(const c of w.PHOENIX_DIAGRAMS.randomSources)assert.equal(w.PHOENIX_ROUTE.tasks[c.id],undefined);});
test('canonical diagram titles sort alphabetically without stripping the first word',()=>{const {w}=setup(),entries=w.PHOENIX_DIAGRAMS.entries,c=w.PhoenixDiagramCatalog;for(let i=1;i<entries.length;i++)assert.ok(c.compareTitles(entries[i-1],entries[i])<=0);assert.equal(c.letterOf("Amateur's armor repair kit diagram"),'A');assert.equal(c.letterOf('Greater Glyph of Quen diagram'),'G');assert.equal(c.letterOf('Viper steel sword diagram'),'V');});
test('letter jump finds only a matching item within the supplied source-filtered entries',()=>{const {w}=setup(),c=w.PhoenixDiagramCatalog,list=w.PHOENIX_DIAGRAMS.entries.filter(e=>e.kind==='fixed');assert.equal(c.firstForLetter(list,'A'),undefined);assert.equal(c.firstForLetter(list,'V').id,'diagram-viper-silver');assert.equal(c.firstForLetter([],'V'),undefined);});
